/**
 * Persistence-layer contracts: page data, media and file storage.
 *
 * IStorageAdapter — CRUD for pages and media metadata (Postgres by default).
 * IPublishAdapter — publication file storage (S3/Yandex by default).
 *
 * The account contract (`IAuthAdapter`) lives in `authAdapters.d.ts`: it cannot
 * move out to an external backend, it has other consumers and another reason to
 * change.
 *
 * A custom adapter is registered by the consumer from their own Nitro plugin
 * through the setters in `modules/persistence/server/registry.ts`.
 */
import type {
    IBricksPageRow,
    TBricksPageSummaryRow,
    ICreatePagePayload,
    IUpdatePagePayload,
    IPageVersionSummary,
    IPageVersion,
} from '../../common/types/bricks-api';
import type { IMediaCategory, IMediaItem } from '../../common/types/media';
import type {
    IBricksTemplateRow,
    ICreateTemplatePayload,
    IUpdateTemplatePayload,
    TBricksTemplateSummary,
} from '../../common/types/templates';
import type { IBricksPageAddress } from '../../common/types/pageAddress';

/**
 * Data for creating a media record. The id is always generated by storage;
 * `uploadedAt` is generated only when the payload omits it — the bucket import passes
 * the object's own date so that an imported file does not date from the import.
 */
export interface ICreateMediaPayload {
    url: string;
    filename: string;
    size: number;
    mimeType: string;
    category: string | null;
    svgContent?: string | null;
    alt?: string;
    uploadedAt?: string;
    /** Pixel dimensions of a raster; not passed for svg and video. */
    width?: number | null;
    height?: number | null;
    /** URLs of the progressive-loading downscaled variants; null — no variants. */
    previewUrl?: string | null;
    mockUrl?: string | null;
}

/**
 * Partial update of media metadata.
 */
export type TUpdateMediaPayload = Partial<Pick<IMediaItem, 'filename' | 'alt' | 'category'>>;

/**
 * Data for creating a media category. `slug` is computed by the caller (from the
 * label), not by storage: the caller needs that same slug for the response about
 * an already existing category.
 */
export interface ICreateMediaCategoryPayload {
    slug: string;
    label: string;
}

/**
 * Outcome of deleting a category. `null` — no category with that slug exists
 * (the handler answers 404); otherwise — how many files lost the category.
 */
export type TDeleteMediaCategoryResult = { clearedCount: number } | null;

/**
 * CRUD for builder pages and media metadata.
 */
export interface IStorageAdapter {
    /**
     * Storage readiness check for `GET /api/bricks/health/ready`: resolve —
     * storage is reachable, reject — the handler answers 503. The method is
     * optional, but an adapter without it is NOT considered ready
     * automatically: readiness runs the fallback probe `listPages()` — the
     * smallest real editorial request. The default Postgres adapter runs
     * `SELECT 1` (and skips the check when the connection string is not
     * configured — proxy mode with no local database).
     *
     * Production adapters MUST implement this method: a cheap targeted check
     * instead of a fallback listing, which can be expensive and runs on every
     * orchestrator probe.
     */
    checkHealth?(): Promise<void>;
    /**
     * Summaries of every page WITHOUT the `schema` field (the editorial list:
     * dashboard, preview resolver). Only the point lookups getPage and
     * getPageByAddress must return the full row with the schema.
     */
    listPages(): Promise<TBricksPageSummaryRow[]>;
    getPage(id: number): Promise<IBricksPageRow | null>;
    /**
     * A page by its full address (`urlPrefix` + `pagename`); null — no such page.
     *
     * By address, not by name: a name is unique only inside its own prefix, and
     * a lookup by name would return an arbitrary one of the same-named pages.
     * The implementation must treat a missing prefix as a value rather than as
     * "any prefix": `/post` must not be found at the address `/blog/post` or the
     * other way round.
     */
    getPageByAddress(address: IBricksPageAddress): Promise<IBricksPageRow | null>;
    createPage(payload: ICreatePagePayload): Promise<IBricksPageRow>;
    /**
     * Updates the passed page fields; null — the page was not found.
     *
     * Versioning contract: when the payload carries `schema` or `viewportConfig`
     * (both are parts of the page's versioned state) and the version limit
     * (`bricks.versionsLimit` / env NUXT_BRICKS_VERSIONS_LIMIT) is above 0, the
     * implementation must atomically snapshot the PREVIOUS row into the version
     * history and trim the page's history down to the limit. A custom adapter
     * is responsible for its own snapshot strategy.
     */
    updatePage(id: number, payload: IUpdatePagePayload): Promise<IBricksPageRow | null>;
    deletePage(id: number): Promise<boolean>;
    /** Summaries of the page's saved versions (no schema), newest first. */
    listPageVersions(pageId: number): Promise<IPageVersionSummary[]>;
    /** Full version snapshot; null — the version is not the page's or was not found. */
    getPageVersion(pageId: number, versionId: number): Promise<IPageVersion | null>;
    listMedia(): Promise<IMediaItem[]>;
    /** Returns a media record by id, or null. */
    getMedia(id: number): Promise<IMediaItem | null>;
    getMediaByUrl(url: string): Promise<IMediaItem | null>;
    /**
     * Creates a media record and returns it with its id.
     *
     * Idempotency contract: `url` is unique; registering the same URL again (a
     * bucket-import race, a client retry, a repeat after an unknown outcome) must
     * return the already existing record rather than fail or create a duplicate.
     *
     * Rejection contract: when the adapter KNOWS the record was not applied it
     * throws `BricksStorageWriteRejectedError` (or a descendant — for instance
     * `BricksUnknownMediaCategoryError` for a missing category). Any other error
     * means an unknown outcome, and the caller will not delete the files it has
     * already uploaded — otherwise the database would keep a row pointing at a
     * deleted object.
     */
    createMedia(payload: ICreateMediaPayload): Promise<IMediaItem>;
    /**
     * Updates media metadata; null — no record with that id.
     *
     * A category named by the payload but absent from the library gives
     * `BricksUnknownMediaCategoryError` (the same rejection contract as createMedia).
     * A payload carrying no category at all is legitimate: the field is simply not
     * written.
     */
    updateMedia(id: number, payload: TUpdateMediaPayload): Promise<IMediaItem | null>;
    deleteMedia(id: number): Promise<boolean>;
    /** Media library categories in display order (by sortOrder, then id). */
    listMediaCategories(): Promise<IMediaCategory[]>;
    /**
     * Creates a category.
     *
     * Idempotency contract: `slug` is unique; creating the same slug again must
     * return the existing record rather than fail — otherwise a double click on
     * "confirm" would show an error over a successfully created category. The caller
     * does not need to tell "created" from "already there": both branches lead to the
     * same UI state.
     */
    createMediaCategory(payload: ICreateMediaCategoryPayload): Promise<IMediaCategory>;
    /**
     * Deletes a category, clearing it off the files.
     *
     * Both halves must be atomic: between clearing the category and deleting the
     * record there must be no state in which `bricks_media.category` points into
     * nothing (which the FK would not allow anyway). There are no preinstalled
     * or undeletable categories — any of them can be deleted, and the files stay
     * in the library, visible under the "All" filter.
     */
    deleteMediaCategory(slug: string): Promise<TDeleteMediaCategoryResult>;
    /**
     * Page template summaries (without `schema` and `pageMeta`, with the block
     * count) — newest first, by CREATION date: renaming a template must not
     * throw its card back to the top of the grid.
     */
    listTemplates(): Promise<TBricksTemplateSummary[]>;
    /** The full template with its schema and styling; `null` — no such template. */
    getTemplate(id: number): Promise<IBricksTemplateRow | null>;
    /**
     * Creates a template and returns it in full.
     *
     * Rejection contract: a taken name is `BricksTemplateNameConflictError`
     * (including on a race between two simultaneous creators: the pre-check does
     * not catch it). There is NO idempotency here and there must not be — a
     * repeated POST with the same name means a second attempt by a person, and a
     * silent "already there" would pass somebody else's template off as the one
     * just saved.
     *
     * `thumbnailUrl` arrives as the template's own file already: the handler
     * copies the page's frame, because a link to the page's frame does not
     * survive its next save (the `prunePageThumbnails` sweep knows nothing about
     * templates).
     */
    createTemplate(payload: ICreateTemplatePayload): Promise<IBricksTemplateRow>;
    /**
     * Edits the template's label (name and/or description); `null` — no such
     * template. A taken name is `BricksTemplateNameConflictError`.
     */
    updateTemplate(id: number, payload: IUpdateTemplatePayload): Promise<IBricksTemplateRow | null>;
    /**
     * Deletes a template; `null` — no such template (the handler answers 404),
     * otherwise — the URL of its preview file, now left with no link to it.
     *
     * The result carries `thumbnailUrl` rather than a `boolean`: the preview file
     * is removed by the handler, and without the URL from this same request it
     * would have to read the row up front — meaning a "two deleting one
     * template" race would leave the file in storage forever.
     * `thumbnailUrl: null` — there is nothing to remove.
     */
    deleteTemplate(id: number): Promise<TDeleteTemplateResult>;
}

/**
 * The media half of the storage contract — the owner of the rationale both
 * implementations point at.
 *
 * Each adapter assembles this half in a file of its own and mixes it into its contract
 * with a spread. The split is along the domain's seam: pages and media share not a
 * single query, and together an adapter file outgrows the 500-line ceiling. The name is
 * a single one and lives here rather than as two copies in the implementations,
 * because their method sets must match — a copy would let Postgres and HTTP drift
 * apart silently.
 */
export type TStorageMediaMethods = Pick<
    IStorageAdapter,
    | 'listMedia'
    | 'getMedia'
    | 'getMediaByUrl'
    | 'createMedia'
    | 'updateMedia'
    | 'deleteMedia'
    | 'listMediaCategories'
    | 'createMediaCategory'
    | 'deleteMediaCategory'
>;

/**
 * Outcome of deleting a template. `null` — no template with that id; otherwise —
 * the URL of the deleted record's preview file (`null` inside — there was no
 * preview).
 */
export type TDeleteTemplateResult = { thumbnailUrl: string | null } | null;

/**
 * The half of the storage contract covering page templates. Split off and named
 * centrally for the same reasons as `TStorageMediaMethods` above.
 */
export type TStorageTemplateMethods = Pick<
    IStorageAdapter,
    'listTemplates' | 'getTemplate' | 'createTemplate' | 'updateTemplate' | 'deleteTemplate'
>;

/**
 * Access to the category list — everything the product rules in
 * `server/utils/mediaCategoryRules.ts` need. A narrow Pick, so that the rules
 * are unit-tested without a real Postgres.
 */
export type TMediaCategoryStorage = Pick<IStorageAdapter, 'listMediaCategories'>;

/**
 * Parameters for uploading a file into the publication storage.
 */
export interface IUploadFileParams {
    buffer: Buffer;
    mimeType: string;
    key: string;
}

/**
 * Parameters for uploading a file into the publication storage as a stream.
 *
 * The bytes arrive in pieces and are never held in full: a video of a hundred
 * megabytes used to be assembled in memory whole, and the parsing of the form
 * copied it once more.
 */
export interface IUploadFileStreamParams {
    key: string;
    mimeType: string;
    /**
     * The bytes as they arrive. The iterable throwing is a refusal to finish the
     * upload — the implementation must not leave anything behind in storage.
     */
    body: AsyncIterable<Uint8Array>;
    /**
     * The ceiling the caller enforces on the stream. The implementation may size
     * its own buffers by it; it is NOT a permission to read further — whoever
     * pipes the bytes is the one who refuses an oversized file.
     */
    maxBytes: number;
    /**
     * Aborted when the client goes away: a request in flight must stop instead of
     * finishing an upload nobody will hear about.
     */
    signal: AbortSignal;
}

/**
 * Result of a file upload.
 */
export interface IUploadedFile {
    url: string;
    key: string;
    size: number;
}

/**
 * Description of a file in storage (for importing existing media).
 */
export interface IStoredFileInfo {
    key: string;
    url: string;
    size: number;
    lastModified: string;
}

/**
 * The kind of publication-storage file — decides the key's namespace prefix.
 *
 * `avatar` — a profile photo. A namespace of its own rather than the media
 * library: were avatars to land in the gallery, any editor would see them among
 * the working files and could delete somebody else's photo, and the bucket
 * import would register them as media.
 */
export type TPublishFileKind = 'media' | 'thumbnail' | 'avatar';

/**
 * Publication file storage (media files).
 *
 * A managed namespace: the adapter owns a limited set of key prefixes (for the
 * S3 default — `prefix`, `thumbnailsPrefix` and `avatarsPrefix` of the
 * configuration). Every key is built through `buildFileKey`, and
 * `deleteFile`/`isOwnedUrl` must refuse keys outside the namespace —
 * in a shared bucket the module must not be able to touch foreign objects even
 * by a syntactically valid bucket URL.
 */
export interface IPublishAdapter {
    /**
     * Builds the full object key for a new module file (server-generated: client
     * names never make it into the key). The single source of prefixes — the
     * handlers do not assemble keys themselves.
     */
    buildFileKey(kind: TPublishFileKind, filename: string): string;
    /**
     * Puts a file into storage under an already built key.
     *
     * On success returns the public URL. On refusal the adapter must
     * best-effort delete the object under that key and rethrow the ORIGINAL
     * error: a failed send does not prove the object is absent — the response
     * could have been lost or hit a timeout after the write already happened,
     * and then the object would stay with no link to it forever (the caller
     * received no URL and has nothing to delete). The object's absence is not
     * guaranteed either: if the cleanup failed too, invisible garbage stays
     * behind — cheaper than a lost upload error.
     *
     * The key must be a NEW one: overwriting an existing object through this
     * entry point is not supported, otherwise the compensation would wipe a live
     * file.
     */
    uploadFile(params: IUploadFileParams): Promise<IUploadedFile>;
    /**
     * Puts a file into storage READING IT AS A STREAM, under an already built key.
     *
     * The method exists because a file that needs no processing (a video) must not
     * be assembled in memory: the peak of one upload was twice the file's size,
     * and two of them at once were enough to take the whole process down with an
     * out-of-memory.
     *
     * The obligations are the same as `uploadFile`'s, plus two of the streaming
     * kind. The bytes may be read once and only forward. Any refusal — a storage
     * error, an exception out of the body iterable (the size ceiling, a validation
     * that failed on the first bytes, a client that went away) — must leave
     * NOTHING behind: a multipart upload begun is aborted, an object that may
     * have been written is deleted best-effort, and the ORIGINAL error is
     * rethrown, because it is the reason the caller has to see.
     *
     * A storage whose protocol cannot upload in pieces is free to buffer the
     * stream — the contract promises the caller a bounded memory footprint of ITS
     * own, not of the implementation's.
     */
    uploadFileStream(params: IUploadFileStreamParams): Promise<IUploadedFile>;
    /**
     * Deletes a file by its public URL. Obliged to throw when the URL does not
     * belong to its own storage or the key lies outside the managed namespace.
     */
    deleteFile(url: string): Promise<void>;
    listFiles(prefix?: string): Promise<IStoredFileInfo[]>;
    /**
     * Reads the head of a stored object — the bytes the format is decided by.
     *
     * Reading goes through the adapter rather than over the public URL of the
     * file: the object need not be public at all, an HTTP fetch by a URL would
     * open a second path out of the server, and the bound on what is read belongs
     * to whoever owns the storage contract. An implementation is obliged to
     * refuse a key outside the managed namespace, exactly as `deleteFile` does.
     *
     * Returns at most `maxBytes`, and fewer for a shorter object.
     */
    readFileHead(key: string, maxBytes: number): Promise<Buffer>;
    /**
     * Checks that the URL points at a file of its own storage inside the managed
     * namespace.
     *
     * Anti-SSRF contract: the server proxies (/api/bricks/media/s3-proxy) and
     * deletes (media orchestration) only URLs that passed this check —
     * arbitrary hosts (localhost, cloud metadata, private network) must not pass
     * it. A custom implementation must check the URL against ITS OWN
     * storage (the key prefix included), not against the URL format in general.
     */
    isOwnedUrl(url: string): boolean;
}

/**
 * Options of the page preview file sweep (`prunePageThumbnails`).
 */
export interface IPrunePageThumbnailsOptions {
    /**
     * Lifts the protection of recently uploaded files. Set when a page is
     * deleted: there will be no next sweep pass there, and a deferred file would
     * stay in storage forever.
     */
    includeRecentUploads?: boolean;
}

/**
 * Dependencies of the post-frame-upload orphan sweep
 * (`prunePageThumbnailsAfterUpload`): narrow Pick contracts instead of full
 * adapters — the logic is tested without Postgres and S3.
 */
export interface IPageThumbnailPruneDeps {
    storage: Pick<IStorageAdapter, 'getPage' | 'listPageVersions'>;
    publish: Pick<IPublishAdapter, 'buildFileKey' | 'listFiles' | 'deleteFile'>;
}
